(function(){const a=document.currentScript;if(a.hasAttribute("data-child")){new ResizeObserver(()=>parent.postMessage({qcalc:document.body.scrollHeight},"*")).observe(document.body);return}const c=new URL(a.src).origin;document.querySelectorAll("[data-qcalc]").forEach(e=>{const t=document.createElement("iframe");t.src=`${c}/calc/core/${encodeURIComponent(e.dataset.qcalc)}/?embed=1`+(e.dataset.run==="false"?"":"&run")+(e.dataset.query?"&"+e.dataset.query:""),t.title=e.dataset.qcalc,t.loading="lazy",t.style.cssText=`width:100%;border:0;min-height:${parseInt(e.dataset.height,10)||480}px`,e.replaceWith(t)}),addEventListener("message",e=>{e.origin!==c||!e.data||!e.data.qcalc||document.querySelectorAll("iframe").forEach(t=>{t.contentWindow===e.source&&(t.style.height=e.data.qcalc+"px")})})})();
